/**
 * The only component that renders icons (`design/components/icon.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/icon.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Glyph } from './Glyph'
import { createDerived, type Defaults } from '../conventions/cells'
import { claimSlot } from '../conventions/slotted'
import type { IconRole } from '@polymorph/engine'
import styles from './icon.module.css'

export interface IconProps {
  /**
   * Accessible name: set it for a meaningful icon (`role="img"` + `aria-label`), omit it for a
   * decorative one (`aria-hidden`), and omit it inside an icon-only Button, which uses its own
   * `label`.
   */
  label?: string
  /**
   * A meaning from the closed role enum, never a glyph name.
   */
  name: IconRole
  size?: 'sm' | 'md' | 'lg'
}

/** The only component that renders icons. */
export default function Icon(given: IconProps): JSX.Element {
  const props = mergeProps({ size: 'md' } as Defaults<IconProps, 'size'>, claimSlot(given))
  const meaningful = createDerived(() => props.label !== undefined)
  return (
    <Glyph
      class={styles.icon}
      glyph={props.name}
      data-size={props.size}
      data-icon={props.name}
      aria-hidden={!meaningful.value ? true : undefined}
      role={meaningful.value ? 'img' : undefined}
      aria-label={props.label}
      data-member="icon"
    />
  )
}
